#include <Cellerator/compiler/lto/implement_elf_ceir_sections_v1.hh>
#include <cstring>
namespace cellerator::compiler::lto::v1 {namespace{template<class T>void put(std::vector<std::uint8_t>&o,T v){auto*p=reinterpret_cast<const std::uint8_t*>(&v);o.insert(o.end(),p,p+sizeof v);}template<class T>bool get(const std::vector<std::uint8_t>&b,std::size_t&n,T&v){if(n+sizeof v>b.size())return false;std::memcpy(&v,b.data()+n,sizeof v);n+=sizeof v;return true;}void text(std::vector<std::uint8_t>&o,const std::string&s){put(o,std::uint32_t(s.size()));o.insert(o.end(),s.begin(),s.end());}bool read(const std::vector<std::uint8_t>&b,std::size_t&n,std::string&s){std::uint32_t z;if(!get(b,n,z)||n+z>b.size())return false;s.assign(reinterpret_cast<const char*>(b.data()+n),z);n+=z;return true;}}
bool validate_elf_ceir_section_v1(const elf_ceir_section_v1&s)noexcept{return s.name.rfind(".cellerator.ceir",0)==0&&!s.payload.empty()&&!s.allocatable&&!s.symbol.empty();}
std::vector<std::uint8_t> emit_elf_ceir_section_v1(const elf_ceir_section_v1&s){if(!validate_elf_ceir_section_v1(s))return{};std::vector<std::uint8_t>o{'C','E','E','L','F','1'};text(o,s.name);text(o,s.note);text(o,s.symbol);put(o,std::uint8_t(s.compression));put(o,std::uint8_t(s.retain_when_stripped));put(o,std::uint32_t(s.payload.size()));o.insert(o.end(),s.payload.begin(),s.payload.end());return o;}
std::optional<elf_ceir_section_v1> extract_elf_ceir_section_v1(const std::vector<std::uint8_t>&b){if(b.size()<6||std::memcmp(b.data(),"CEELF1",6))return{};std::size_t n=6;elf_ceir_section_v1 s;std::uint8_t c,r;std::uint32_t z;if(!read(b,n,s.name)||!read(b,n,s.note)||!read(b,n,s.symbol)||!get(b,n,c)||!get(b,n,r)||!get(b,n,z)||n+z!=b.size())return{};s.compression=static_cast<elf_ceir_compression_v1>(c);s.retain_when_stripped=r;s.payload.assign(b.begin()+n,b.end());return s;}
std::vector<std::uint8_t> strip_elf_runtime_symbols_v1(const std::vector<std::uint8_t>&b){auto s=extract_elf_ceir_section_v1(b);return s&&s->retain_when_stripped?b:std::vector<std::uint8_t>{};}
}
